Here's the fetch moved into a reusable `useUser` hook, with loading and error state:

```tsx
import { useEffect, useState } from "react";

export function useUser(id: string) {
  const [user, setUser] = useState<User | null>(null);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch(`/api/users/${id}`)
      .then((r) => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        return r.json();
      })
      .then((data) => !cancelled && setUser(data))
      .catch((e) => !cancelled && setError(e));
    return () => {
      cancelled = true;
    };
  }, [id]);

  return { user, error, loading: !user && !error };
}
```

```tsx
export function Profile({ id }: { id: string }) {
  const { user, error, loading } = useUser(id);
  if (loading) return <p>Loading…</p>;
  if (error) return <p>Something went wrong.</p>;
  return <h1>{user!.name}</h1>;
}
```

The `cancelled` flag prevents setting state after the component unmounts or `id` changes mid-request.

