Add a `toggle` function that flips `done` for the clicked item, and style completed items with a strikethrough:

```tsx
function toggle(id: number) {
  setTodos((prev) =>
    prev.map((t) => (t.id === id ? { ...t, done: !t.done } : t)),
  );
}

// in the JSX
<ul>
  {todos.map((t) => (
    <li
      key={t.id}
      onClick={() => toggle(t.id)}
      style={{
        textDecoration: t.done ? "line-through" : "none",
        cursor: "pointer",
      }}
    >
      {t.text}
    </li>
  ))}
</ul>
```

Clicking an item marks it complete; clicking again un-marks it. If you'd rather use a checkbox, render `<input type="checkbox" checked={t.done} onChange={() => toggle(t.id)} />` inside each `<li>`.

